def clean_editor(t):
 for m in ['V386_MOBILE_EDITOR_REFERENCE_LOCK','V387_MOBILE_EDITOR_PLAYER_VISIBILITY','V388_MOBILE_EDITOR_REFERENCE_FINAL']:
  t=re.sub(r'\s*<!-- '+m+r' -->.*?</script>\s*','\n',t,flags=re.S)
 return t
def clean_shell(t):
 for sid in ['v386EditorParentReference','v387EditorIframeFill','v388ParentIframeFill']:
  t=re.sub(r'\s*<style id="'+sid+r'">.*?</style>\s*','\n',t,flags=re.S)
 for sid in ['V386_HIDE_DUPLICATE_FINAL_CTA','V388_HIDE_OUTER_SHORT_CTA']:
  t=re.sub(r'\s*<script id="'+sid+r'">.*?</script>\s*','\n',t,flags=re.S)
 return t
